def havel_hakimi(seq):
    seq = sorted(seq, reverse=True)
    while seq and seq[0] > 0:
        d = seq.pop(0)
        if d > len(seq):
            return False
        for i in range(d):
            seq[i] -= 1
            if seq[i] < 0:
                return False
        seq.sort(reverse=True)
    return all(x == 0 for x in seq)

def has_eulerian_cycle(adj):
    # adj : liste d'adjacence (dict sommet -> liste voisins)
    # graphe non orienté, connexe supposé
    for v in adj:
        if len(adj[v]) % 2 != 0:
            return False
    return True
